def edit_image(api_key_id, prompt, source_image_asset_id, idempotency_key=None, model=None, size=None, mask_image_asset_id=None, client_ip=None, user_agent=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0433000" if __import__("os").path.isdir("./environment_mix/0433000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- validate inputs (do not over-restrict beyond schema) ----
    if not isinstance(api_key_id, str) or not re.match(r"^dalle_key_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^dalle_key_[0-9A-Za-z]+$.")
    if not isinstance(prompt, str) or not prompt.strip():
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string.")
    # NOTE: datastore contains asset ids like dalle_asset_... too; accept any string id here and validate by lookup.
    if not isinstance(source_image_asset_id, str) or not source_image_asset_id.strip():
        return _err("VALIDATION_ERROR", "source_image_asset_id must be a non-empty string.")
    if mask_image_asset_id is not None and (not isinstance(mask_image_asset_id, str) or not mask_image_asset_id.strip()):
        return _err("VALIDATION_ERROR", "mask_image_asset_id must be a non-empty string when provided.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
    if model is not None and not isinstance(model, str):
        return _err("VALIDATION_ERROR", "model must be a string when provided.")
    if size is not None and not isinstance(size, str):
        return _err("VALIDATION_ERROR", "size must be a string when provided.")
    if client_ip is not None and not isinstance(client_ip, str):
        return _err("VALIDATION_ERROR", "client_ip must be a string when provided.")
    if user_agent is not None and not isinstance(user_agent, str):
        return _err("VALIDATION_ERROR", "user_agent must be a string when provided.")

    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")
    image_jobs = _load("image_jobs.json")
    image_assets = _load("image_assets.json")

    def _ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        # IDs in store look like dalle_req_01..., dalle_job_01..., dalle_img_01...
        return f"{prefix}_01{secrets.token_urlsafe(14).replace('-','').replace('_','')[:24]}"

    def _req_log(status, api_key_id_for_log, error_code=None, error_message=None, request_id=None, idempotency_key_to_set=None):
        rid = request_id or _new_id("dalle_req")
        row = {
            "id": rid,
            "tool_name": "edit_image",
            "api_key_id": api_key_id_for_log,
            "idempotency_key": idempotency_key_to_set,
            "client_ip": client_ip,
            "user_agent": user_agent,
            "input_payload": {
                "api_key_id": api_key_id,
                "idempotency_key": idempotency_key,
                "prompt": prompt,
                "model": model,
                "size": size,
                "source_image_asset_id": source_image_asset_id,
                "mask_image_asset_id": mask_image_asset_id,
                "client_ip": client_ip,
                "user_agent": user_agent,
            },
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": _ms() if status in ("succeeded", "failed") else None,
            "created_at": now,
            "updated_at": now,
        }
        requests_rows.append(row)
        _save("requests.json", requests_rows)
        return row

    # ---- idempotency: if exists, return previous outcome and do not create new jobs/assets ----
    if idempotency_key is not None:
        existing_req = None
        for r in requests_rows:
            if r.get("idempotency_key") == idempotency_key:
                existing_req = r
                break
        if existing_req is not None:
            existing_jobs = [j for j in image_jobs if j.get("request_id") == existing_req.get("id")]
            out_assets = [a for a in image_assets if a.get("job_id") in {j.get("id") for j in existing_jobs} and a.get("asset_role") == "output" and a.get("status") != "deleted"]
            return {
                "request": existing_req,
                "jobs": existing_jobs,
                "output_assets": out_assets,
                "idempotent_replay": True,
            }

    # ---- resolve api key + enforce key eligibility ----
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key_id:
            key_row = k
            break
    if key_row is None:
        req = _req_log("failed", api_key_id, error_code="invalid_request", error_message="api_key_id not found.")
        return _err("NOT_FOUND", "api_key_id not found.", request_id=req.get("id"))

    if key_row.get("status") == "disabled":
        req = _req_log("failed", api_key_id, error_code="invalid_key", error_message="API key is disabled.")
        try:
            key_row["requests_total"] = int(key_row.get("requests_total") or 0) + 1
            key_row["updated_at"] = now
            _save("api_keys.json", api_keys)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key is disabled.", request_id=req.get("id"))

    # ---- validate source/mask assets by lookup and business rules ----
    src = None
    for a in image_assets:
        if a.get("id") == source_image_asset_id:
            src = a
            break
    if src is None:
        req = _req_log("failed", api_key_id, error_code="invalid_request", error_message="source_image_asset_id not found.")
        return _err("NOT_FOUND", "source_image_asset_id not found.", request_id=req.get("id"))
    if src.get("status") != "stored" or src.get("asset_role") != "input":
        req = _req_log(
            "failed",
            api_key_id,
            error_code="invalid_request",
            error_message="For edit jobs, source_image_asset_id must reference a stored image_assets row with asset_role='input' (and not deleted).",
        )
        return _err(
            "VALIDATION_ERROR",
            "For edit jobs, source_image_asset_id must reference an image_assets row with status='stored' and asset_role='input'. Deleted/staged assets cannot be used.",
            request_id=req.get("id"),
        )

    mask = None
    if mask_image_asset_id is not None:
        for a in image_assets:
            if a.get("id") == mask_image_asset_id:
                mask = a
                break
        if mask is None:
            req = _req_log("failed", api_key_id, error_code="invalid_request", error_message="mask_image_asset_id not found.")
            return _err("NOT_FOUND", "mask_image_asset_id not found.", request_id=req.get("id"))
        if mask.get("status") != "stored" or mask.get("asset_role") != "mask":
            req = _req_log(
                "failed",
                api_key_id,
                error_code="invalid_request",
                error_message="For edit jobs, mask_image_asset_id must reference a stored image_assets row with asset_role='mask' (and not deleted).",
            )
            return _err(
                "VALIDATION_ERROR",
                "For edit jobs, mask_image_asset_id (when provided) must reference an image_assets row with status='stored' and asset_role='mask'. Deleted/staged assets cannot be used.",
                request_id=req.get("id"),
            )

    # ---- rate limiting (rpm/rpd) and counters ----
    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rpm = int(key_row.get("rate_limit_rpm") or 0)
    rpd = int(key_row.get("rate_limit_rpd") or 0)

    window_60 = now_dt - datetime.timedelta(seconds=60)
    window_day = now_dt - datetime.timedelta(days=1)

    recent_reqs = [r for r in requests_rows if r.get("api_key_id") == api_key_id and r.get("tool_name") in ("generate_image", "edit_image", "create_variation")]
    count_60 = 0
    count_day = 0
    for r in recent_reqs:
        ts = _parse_iso(r.get("created_at"))
        if ts is None:
            continue
        if ts >= window_60:
            count_60 += 1
        if ts >= window_day:
            count_day += 1

    if (rpm > 0 and count_60 >= rpm) or (rpd > 0 and count_day >= rpd):
        req = _req_log("failed", api_key_id, error_code="rate_limited", error_message="Rate limit exceeded.")
        try:
            key_row["requests_total"] = int(key_row.get("requests_total") or 0) + 1
            key_row["updated_at"] = now
            _save("api_keys.json", api_keys)
        except Exception:
            pass
        return _err("RATE_LIMIT", "Rate limit exceeded for this api_key_id.", request_id=req.get("id"))

    # ---- create request + job ----
    req_row = _req_log("running", api_key_id, request_id=None, idempotency_key_to_set=idempotency_key)
    job_id = _new_id("dalle_job")
    job_row = {
        "id": job_id,
        "request_id": req_row["id"],
        "api_key_id": api_key_id,
        "job_type": "edit",
        "status": "succeeded",  # offline simulation: immediate success
        "prompt": prompt,
        "model": model,
        "n": 1,
        "size": size,
        "source_image_asset_id": source_image_asset_id,
        "mask_image_asset_id": mask_image_asset_id,
        "upstream_request_id": None,
        "upstream_response": {"simulated": True},
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    }
    image_jobs.append(job_row)
    _save("image_jobs.json", image_jobs)

    # ---- create output asset(s) on success ----
    out_asset_id = _new_id("dalle_img")
    out_asset = {
        "id": out_asset_id,
        "job_id": job_id,
        "asset_role": "output",
        "status": "stored",
        "mime_type": "image/png",
        "byte_size": 0,
        "width": None,
        "height": None,
        "sha256": None,
        "storage_backend": "openai_url",
        "storage_key": None,
        "external_url": f"https://example.invalid/openai/assets/{out_asset_id}",
        "expires_at": (now_dt + datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z",
        "created_at": now,
        "updated_at": now,
    }
    image_assets.append(out_asset)
    _save("image_assets.json", image_assets)

    # ---- finalize request: succeeded only if all jobs succeeded ----
    # update request row in place
    for r in requests_rows:
        if r.get("id") == req_row["id"]:
            r["status"] = "succeeded"
            r["duration_ms"] = _ms()
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("requests.json", requests_rows)

    # ---- increment api key counters ----
    try:
        key_row["requests_total"] = int(key_row.get("requests_total") or 0) + 1
        key_row["images_total"] = int(key_row.get("images_total") or 0) + 1
        key_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("api_keys.json", api_keys)
    except Exception:
        pass

    return {
        "request": next((r for r in requests_rows if r.get("id") == req_row["id"]), req_row),
        "job": job_row,
        "output_assets": [out_asset],
    }

