        except Exception:
            return None

    def _req_log(status, api_key_id_for_log, error_code=None, error_message=None, request_id=None, idempotency_key_to_set=None):
        rid = request_id or _new_id("dalle_req")
        row = {
            "id": rid,
            "tool_name": "create_variation",
            "api_key_id": api_key_id_for_log,
            "idempotency_key": idempotency_key_to_set,
            "client_ip": client_ip,
            "user_agent": user_agent,
            "input_payload": {
                "api_key_id": api_key_id,
                "idempotency_key": idempotency_key,
                "model": model,
                "size": size,
                "source_image_asset_id": source_image_asset_id,
                "client_ip": client_ip,
                "user_agent": user_agent,
            },
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": _ms() if status in ("succeeded", "failed") else None,
            "created_at": now,
            "updated_at": now,
        }
        requests_rows.append(row)
        _save("requests.json", requests_rows)
        return row

    # Idempotency replay
    if idempotency_key is not None:
        for r in requests_rows:
            if r.get("idempotency_key") == idempotency_key:
                existing_jobs = [j for j in image_jobs if j.get("request_id") == r.get("id")]
                out_assets = [a for a in image_assets if a.get("job_id") in {j.get("id") for j in existing_jobs} and a.get("asset_role") == "output" and a.get("status") != "deleted"]
                return {
                    "request": r,
                    "jobs": existing_jobs,
                    "output_assets": out_assets,
                    "idempotent_replay": True,
                }

    # API key exists and is usable
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key_id:
