            _save("api_keys.json", api_keys)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key is disabled.", request_id=req.get("id"))

    # Source asset must be stored input and not deleted
    src = None
    for a in image_assets:
        if a.get("id") == source_image_asset_id:
            src = a
            break
    if src is None:
        req = _req_log("failed", api_key_id, error_code="invalid_request", error_message="source_image_asset_id not found.")
        return _err("NOT_FOUND", "source_image_asset_id not found.", request_id=req.get("id"))
