        req = _req_log(
            "failed",
            api_key_id,
            error_code="invalid_request",
            error_message="For variation jobs, source_image_asset_id must reference a stored image_assets row with asset_role='input' (and not deleted).",
        )
        return _err(
            "VALIDATION_ERROR",
            "For variation jobs, source_image_asset_id must reference an image_assets row with status='stored' and asset_role='input'. Deleted/staged assets cannot be used.",
