    # Rate limiting based on request logs
    rpm = int(key_row.get("rate_limit_rpm") or 0)
    rpd = int(key_row.get("rate_limit_rpd") or 0)
    window_60 = now_dt - datetime.timedelta(seconds=60)
    window_day = now_dt - datetime.timedelta(days=1)

    recent_reqs = [r for r in requests_rows if r.get("api_key_id") == api_key_id and r.get("tool_name") in ("generate_image", "edit_image", "create_variation")]
