        if ts is None:
            continue
        if ts >= window_60:
            count_60 += 1
        if ts >= window_day:
            count_day += 1
    if (rpm > 0 and count_60 >= rpm) or (rpd > 0 and count_day >= rpd):
        req = _req_log("failed", api_key_id, error_code="rate_limited", error_message="Rate limit exceeded.")
        try:
            key_row["requests_total"] = int(key_row.get("requests_total") or 0) + 1
            key_row["updated_at"] = now
            _save("api_keys.json", api_keys)
        except Exception:
            pass
        return _err("RATE_LIMIT", "Rate limit exceeded for this api_key_id.", request_id=req.get("id"))

    # Create request + job
    req_row = _req_log("running", api_key_id, idempotency_key_to_set=idempotency_key)
    job_id = _new_id("dalle_job")
    job_row = {
        "id": job_id,
        "request_id": req_row["id"],
        "api_key_id": api_key_id,
        "job_type": "variation",
        "status": "succeeded",  # offline simulation: immediate success
        "prompt": None,
        "model": model,
        "n": 1,
        "size": size,
        "source_image_asset_id": source_image_asset_id,
        "mask_image_asset_id": None,
        "upstream_request_id": None,
        "upstream_response": {"simulated": True},
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    }
    image_jobs.append(job_row)
    _save("image_jobs.json", image_jobs)

    # Output asset
    out_asset_id = _new_id("dalle_img")
    out_asset = {
        "id": out_asset_id,
        "job_id": job_id,
        "asset_role": "output",
        "status": "stored",
        "mime_type": "image/png",
        "byte_size": 0,
        "width": None,
        "height": None,
        "sha256": None,
        "storage_backend": "openai_url",
        "storage_key": None,
        "external_url": f"https://example.invalid/openai/assets/{out_asset_id}",
