        "created_at": now,
        "updated_at": now,
    }
    image_assets.append(out_asset)
    _save("image_assets.json", image_assets)

    # Finalize request status
    for r in requests_rows:
        if r.get("id") == req_row["id"]:
            r["status"] = "succeeded"
            r["duration_ms"] = _ms()
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("requests.json", requests_rows)

    # Counters
    try:
        key_row["requests_total"] = int(key_row.get("requests_total") or 0) + 1
        key_row["images_total"] = int(key_row.get("images_total") or 0) + 1
