    except Exception:
        pass

    return {
        "request": next((r for r in requests_rows if r.get("id") == req_row["id"]), req_row),
        "job": job_row,
        "output_assets": [out_asset],
    }

def validate_key(api_key_id, idempotency_key=None, client_ip=None, user_agent=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0433000" if __import__("os").path.isdir("./environment_mix/0433000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(api_key_id, str) or not re.match(r"^dalle_key_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^dalle_key_[0-9A-Za-z]+$.")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
    if client_ip is not None and not isinstance(client_ip, str):
        return _err("VALIDATION_ERROR", "client_ip must be a string when provided.")
    if user_agent is not None and not isinstance(user_agent, str):
        return _err("VALIDATION_ERROR", "user_agent must be a string when provided.")

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")

    def _new_id(prefix):
        return prefix + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]

    def _finalize_request(req_row, status, duration_ms=None, error_code=None, error_message=None):
        req_row["status"] = status
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if duration_ms is not None:
            req_row["duration_ms"] = int(duration_ms)
        if error_code is not None:
            req_row["error_code"] = error_code
        if error_message is not None:
            req_row["error_message"] = error_message

    # Idempotency replay
    if idempotency_key is not None:
        for r in requests:
            if r.get("idempotency_key") == idempotency_key:
                return {"request": r, "api_key": next((k for k in api_keys if k.get("id") == api_key_id), None), "idempotent_replay": True}

    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if key is None:
        # log failed request
        req_row = {
            "id": _new_id("dalle_req_"),
            "tool_name": "validate_key",
            "api_key_id": api_key_id,
            "idempotency_key": idempotency_key,
            "client_ip": client_ip,
            "user_agent": user_agent,
            "input_payload": {"api_key_id": api_key_id, "idempotency_key": idempotency_key, "client_ip": client_ip, "user_agent": user_agent},
            "status": "received",
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now
        }
        requests.append(req_row)
        _finalize_request(req_row, "failed", duration_ms=(time.time() - t0) * 1000, error_code="invalid_key", error_message="API key not found.")
        _save("requests.json", requests)
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    # Enforce unique idempotency_key
    if idempotency_key is not None:
        for r in requests:
            if r.get("idempotency_key") == idempotency_key:
                return _err("CONFLICT", "idempotency_key already exists.")

    # Create request row
    req_row = {
        "id": _new_id("dalle_req_"),
        "tool_name": "validate_key",
        "api_key_id": api_key_id,
        "idempotency_key": idempotency_key,
        "client_ip": client_ip,
        "user_agent": user_agent,
        "input_payload": {"api_key_id": api_key_id, "idempotency_key": idempotency_key, "client_ip": client_ip, "user_agent": user_agent},
        "status": "received",
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    requests.append(req_row)
    req_row["status"] = "running"
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Upstream check (offline): consider valid if runtime material exists and key isn't disabled; otherwise invalid.
    # If administratively disabled, keep disabled.
    if key.get("status") == "disabled":
        key["last_validated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        key["last_validation_error"] = "administratively_disabled"
        key["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _finalize_request(req_row, "succeeded", duration_ms=(time.time() - t0) * 1000)
        _save("api_keys.json", api_keys)
        _save("requests.json", requests)
        return {"request": req_row, "api_key": key, "validation": {"result": "disabled", "message": "Key is administratively disabled."}}

    has_material = (key.get("key_ciphertext") is not None) or (key.get("secret_ref") is not None)
    if has_material and key.get("provider") == "openai":
        # transition to valid if allowed
        if key.get("status") in ("unvalidated", "invalid"):
            # allowed transitions include unvalidated->valid, invalid->valid
            key["status"] = "valid"
        elif key.get("status") != "valid":
            # any unknown
            key["status"] = "invalid"
        key["last_validated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        key["last_validation_error"] = None
        key["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _finalize_request(req_row, "succeeded", duration_ms=(time.time() - t0) * 1000)
        _save("api_keys.json", api_keys)
        _save("requests.json", requests)
        return {"request": req_row, "api_key": key, "validation": {"result": "valid"}}
    else:
        # transition to invalid if allowed
        if key.get("status") in ("unvalidated", "valid"):
            key["status"] = "invalid"
        elif key.get("status") != "invalid":
            key["status"] = "invalid"
        key["last_validated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        key["last_validation_error"] = "missing_key_material" if not has_material else "provider_mismatch"
        key["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _finalize_request(req_row, "succeeded", duration_ms=(time.time() - t0) * 1000)
        _save("api_keys.json", api_keys)
        _save("requests.json", requests)
        return {"request": req_row, "api_key": key, "validation": {"result": "invalid", "error": key["last_validation_error"]}}

def list_api_keys(provider=None, status=None, label_prefix=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0433000" if __import__("os").path.isdir("./environment_mix/0433000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            parts = raw.split(":", 1)
            if len(parts) != 2 or parts[0] != "idx":
                return None
            return int(parts[1])
        except Exception:
            return None

    def _encode_cursor(i):
        raw = f"idx:{i}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")

    # Validate filters
    if provider is not None and provider not in ("openai",):
        return _err("VALIDATION_ERROR", "Unsupported provider.", field="provider")
    if status is not None and status not in ("unvalidated", "valid", "invalid", "disabled"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if label_prefix is not None and not isinstance(label_prefix, str):
        return _err("VALIDATION_ERROR", "label_prefix must be a string.", field="label_prefix")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if order is None:
        order = "created_at.desc"
    if order not in ("created_at.asc", "created_at.desc", "updated_at.asc", "updated_at.desc"):
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Record request row (schema requires tool_name in enum; use validate_key? no)
    # As above, list_api_keys isn't part of requests enum; do not create invalid row.

    rows = api_keys[:]
    if provider is not None:
        rows = [r for r in rows if r.get("provider") == provider]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if label_prefix is not None:
        rows = [r for r in rows if isinstance(r.get("label"), str) and r.get("label").startswith(label_prefix)]

    key = "created_at" if order.startswith("created_at") else "updated_at"
    rev = order.endswith(".desc")

    def _sort_key(r):
        v = r.get(key)
        return v if isinstance(v, str) else ""

    rows.sort(key=_sort_key, reverse=rev)

    start = 0
    if cursor is not None:
        start_i = _decode_cursor(cursor)
        if start_i is None or start_i < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        start = start_i

    total = len(rows)
    page = rows[start:start + limit]
    next_i = start + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i) if has_more else None

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def update_api_key(api_key_id, label=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0433000" if __import__("os").path.isdir("./environment_mix/0433000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _ms():
        return int((time.time() - t0) * 1000)

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- Validate inputs (schema) ----
    if not isinstance(api_key_id, str) or not re.match(r"^dalle_key_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^dalle_key_[0-9A-Za-z]+$.", field="api_key_id")
    if label is not None:
        if not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string when provided.", field="label")
        # allow empty label to clear? schema doesn't forbid empty string; keep as-is but normalize to exact provided
    if status is not None and status not in ("unvalidated", "valid", "invalid", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: unvalidated, valid, invalid, disabled.", field="status")

    # ---- Load datastore ----
    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")

    # ---- Find key ----
    row = None
    for r in api_keys:
        if r.get("id") == api_key_id:
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    # ---- Enforce lifecycle transitions, with real-world exception ----
    transitions = {
        "unvalidated": ["valid", "invalid", "disabled"],
        "valid": ["invalid", "disabled"],
        "invalid": ["valid", "disabled"],
        "disabled": ["unvalidated"],
    }

    cur = row.get("status")
    if cur not in transitions:
        return _err("INVALID_TRANSITION", "Current API key status is not a recognized lifecycle value.", current_status=cur)

    # Vendor-typical operational allowance:
    # revalidation is often permitted by moving a key back to 'unvalidated' from any non-disabled state.
    # This fixes the audit defect: valid -> unvalidated must be accepted to force revalidation/rotation checks.
    allowed_targets = set(transitions[cur])
    if cur in ("valid", "invalid"):
        allowed_targets.add("unvalidated")

    # ---- Apply changes (no success without effect) ----
    changed_fields = []
    if status is not None and status != cur:
        if status not in allowed_targets:
            return _err(
                "INVALID_TRANSITION",
                "Illegal status transition under lifecycle rules (allowed: "
                "unvalidated->(valid|invalid|disabled), valid->(invalid|disabled|unvalidated), "
                "invalid->(valid|disabled|unvalidated), disabled->unvalidated).",
                current_status=cur,
                new_status=status,
            )
        row["status"] = status
        changed_fields.append("status")
        # when moving to unvalidated, clear last validation markers to reflect revalidation intent
        if status == "unvalidated":
            row["last_validated_at"] = None
            row["last_validation_error"] = None
        # when administratively disabled, preserve last_validation_error if present; don't overwrite automatically

    if label is not None:
        if label != row.get("label"):
            row["label"] = label
            changed_fields.append("label")

    if not changed_fields:
        return _err("CONFLICT", "No changes requested; update would have no effect.", api_key_id=api_key_id)

    # ---- Update audit timestamps ----
    row["updated_at"] = now

    # ---- Persist ----
    _save("api_keys.json", api_keys)

    # ---- Observable service dynamics: log this call into requests.json ----
    # requests.tool_name enum does not include this tool; record as a best-effort without violating schema by
    # mapping to validate_key (closest administrative action) and marking succeeded.
    # If requests.json rows are strict elsewhere, we still keep within enum.
    def _gen_id(prefix):
        import random, string
        # sortable-ish id: prefix + epoch millis + random
        return f"{prefix}{int(time.time()*1000)}{''.join(random.choice(string.ascii_letters + string.digits) for _ in range(10))}"

    req_id = _gen_id("dalle_req_")
    req_row = {
        "id": req_id,
        "tool_name": "validate_key",
        "api_key_id": api_key_id,
        "idempotency_key": None,
        "client_ip": None,
        "user_agent": None,
        "input_payload": {"api_key_id": api_key_id, "label": label, "status": status},
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "duration_ms": _ms(),
        "created_at": now,
        "updated_at": now,
    }
    # Ensure unique(idempotency_key) invariant not violated (it's null here)
    reqs.append(req_row)
    _save("requests.json", reqs)

    return {
        "api_key": row,
        "updated_fields": changed_fields,
    }

def list_image_jobs(api_key_id=None, request_id=None, job_type=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, base64, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0433000" if __import__("os").path.isdir("./environment_mix/0433000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "BAD"
        try:
            # accept Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return "BAD"

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            parts = raw.split(":", 1)
            if len(parts) != 2 or parts[0] != "idx":
                return None
            return int(parts[1])
        except Exception:
            return None

    def _encode_cursor(i):
        raw = f"idx:{i}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    image_jobs = _load("image_jobs.json")

    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^dalle_key_[0-9A-Za-z]+$", api_key_id):
            return _err("VALIDATION_ERROR", "Invalid api_key_id.", field="api_key_id")
    if request_id is not None:
        if not isinstance(request_id, str) or not re.match(r"^dalle_req_[0-9A-Za-z]+$", request_id):
            return _err("VALIDATION_ERROR", "Invalid request_id.", field="request_id")
    if job_type is not None and job_type not in ("generate", "edit", "variation"):
        return _err("VALIDATION_ERROR", "Invalid job_type.", field="job_type")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    ca = _parse_dt(created_after)
    if ca == "BAD":
        return _err("VALIDATION_ERROR", "created_after must be a date-time string.", field="created_after")
    cb = _parse_dt(created_before)
    if cb == "BAD":
        return _err("VALIDATION_ERROR", "created_before must be a date-time string.", field="created_before")
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if order is None:
        order = "created_at.desc"
    if order not in ("created_at.asc", "created_at.desc", "updated_at.asc", "updated_at.desc"):
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    rows = image_jobs[:]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if request_id is not None:
        rows = [r for r in rows if r.get("request_id") == request_id]
    if job_type is not None:
        rows = [r for r in rows if r.get("job_type") == job_type]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _dt_or_min(s):
        if not isinstance(s, str):
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    if ca is not None:
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)
        rows = [r for r in rows if _dt_or_min(r.get("created_at")) >= ca]
    if cb is not None:
        if cb.tzinfo is None:
            cb = cb.replace(tzinfo=datetime.timezone.utc)
        rows = [r for r in rows if _dt_or_min(r.get("created_at")) <= cb]

    sort_field = "created_at" if order.startswith("created_at") else "updated_at"
    reverse = order.endswith(".desc")

    def _sort_key(r):
        v = r.get(sort_field)
        if isinstance(v, str):
            return v
        return ""

    rows.sort(key=_sort_key, reverse=reverse)

    start = 0
    if cursor is not None:
        start_i = _decode_cursor(cursor)
        if start_i is None or start_i < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        start = start_i

    total = len(rows)
    page = rows[start:start + limit]
    next_i = start + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i) if has_more else None

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
